package com.hbm.client.oreslopper;
import com.hbm.machine.electricfurnace.FurnaceUpgradeItem;import com.hbm.machine.crystallizer.EffectUpgradeItem;import net.minecraft.ChatFormatting;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.entity.player.ItemTooltipEvent;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class OreSlopperUpgradeHelp {
 @SubscribeEvent public static void tooltip(ItemTooltipEvent event){if(!(Minecraft.getInstance().screen instanceof OreSlopperScreen))return;var item=event.getItemStack().getItem();if(item instanceof FurnaceUpgradeItem u&&u.type()==FurnaceUpgradeItem.Type.SPEED){event.getToolTip().add(Component.translatable("container.machineOreSlopper").withStyle(ChatFormatting.YELLOW));event.getToolTip().add(Component.translatable("upgrade.delay","-"+u.tier()*25+"%").withStyle(ChatFormatting.GREEN));event.getToolTip().add(Component.translatable("upgrade.consumption","+"+u.tier()*50+"%").withStyle(ChatFormatting.RED));}else if(item instanceof EffectUpgradeItem u){event.getToolTip().add(Component.translatable("container.machineOreSlopper").withStyle(ChatFormatting.YELLOW));event.getToolTip().add(Component.translatable("upgrade.efficiency","+"+u.tier()*10+"%").withStyle(ChatFormatting.GREEN));event.getToolTip().add(Component.translatable("upgrade.consumption","+"+u.tier()*100+"%").withStyle(ChatFormatting.RED));}}
 private OreSlopperUpgradeHelp(){}
}
